function orbMarkup(id){if(id==='tourfixer')return `<div class="detail-orb"><img src="assets/tourfixer-icon.svg" width="80" height="80" alt=""><span>Let curiosity take you places.</span></div>`;if(id==='advoai')return `<div class="detail-orb advo-detail"><strong>✳</strong><span>Ideas, out in the world.</span></div>`;return `<div class="detail-orb prava-detail"><strong>G↗</strong><span>Always moving forward.</span></div>`}
function rowMarkup(id){const p=projectData[id];const orb=id==='txielts'?'<img src="assets/txielts-icon.svg" width="38" height="38" alt="">':id==='tourfixer'?'<img src="assets/tourfixer-icon.svg" width="38" height="38" alt="">':id==='advoai'?'<img src="assets/advoai-icon.png" width="38" height="38" alt="">':'G↗';return `<button class="project-row tactile" data-project="${id}"><span class="row-orb ${id==='advoai'?'advo-orb':id==='goprava'?'prava-orb':''}">${orb}</span><span class="row-copy"><strong>${p.name}</strong><small>${id==='txielts'?'A clearer path to IELTS practice.':id==='tourfixer'?'Where building meets travel.':id==='advoai'?'Legal questions, made conversational.':'In progress — the next chapter.'}</small></span><span class="row-arrow">↗</span></button>`}
function pageMarkup(view){const extension=window.portfolioExtras?.page(view);if(extension)return extension;if(projectData[view])return projectStoryMarkup(view);if(view==='work')return `<p class="panel-eyebrow">A few things I’ve put into the world</p><h2 class="panel-title" id="panel-title">From an idea.<br>To <span class="soft-text">something real.</span></h2><p class="panel-lead">Four different projects. The same curiosity behind them.</p><div class="project-list">${['tourfixer','advoai','txielts','goprava'].map(rowMarkup).join('')}</div><button class="inline-discovery tactile" data-open="travel">${icon('plane')} Follow the travel-tech thread <span>↗</span></button>`;if(view==='about')return `<div class="about-layout"><div><p class="panel-eyebrow">The human behind the pixels</p><h2 class="panel-title" id="panel-title">To’rabek<br><span class="soft-text">Raufov.</span></h2><p class="panel-lead">I’m a full-stack developer, project manager, entrepreneur, and design enthusiast.</p><p class="panel-lead">I like connecting the dots between an idea, the people behind it, and the product it becomes. Travel tech has a special place in my world.</p><div class="about-facts"><span>Build with care</span><span>Think in possibilities</span><span>Notice the details</span></div><div class="about-footnote">${icon('plane')} Currently curious about the future of travel tech.</div><a class="panel-link cv-panel-link tactile" href="/files/Torabek_Raufov_CV.pdf?v=4858b55cf74f" download="Torabek_Raufov_CV.pdf">Download CV <span aria-hidden="true">↓</span></a><button class="inline-discovery tactile" data-open="now">What’s in my orbit right now <span>↗</span></button></div><div class="detail-orb about-detail" aria-hidden="true"><span class="orb-eyes">• •</span><i class="orb-smile"></i></div></div>`;return `<div class="contact-layout"><div class="contact-mini-orb">${icon('chat')}</div><p class="panel-eyebrow">No pitch required</p><h2 class="panel-title" id="panel-title">Let’s <span class="soft-text">talk.</span></h2><p class="panel-lead">An interesting thought, a question,<br>or just a wave. I’m all ears.</p><a class="panel-link tactile" href="https://t.me/t6rabek" target="_blank" rel="noopener">Let’s talk on Telegram${icon('arrow')}</a><a class="panel-link cv-panel-link tactile" href="/files/Torabek_Raufov_CV.pdf?v=4858b55cf74f" download="Torabek_Raufov_CV.pdf">Download CV <span aria-hidden="true">↓</span></a><div class="social-links"><a href="https://github.com/t6rabek" target="_blank" rel="noopener">GitHub ↗</a><a href="https://www.linkedin.com/in/t6rabek/" target="_blank" rel="noopener">LinkedIn ↗</a><a href="https://t.me/t6rabek" target="_blank" rel="noopener">Telegram ↗</a></div><p class="contact-note">A connection can lead somewhere interesting.</p></div>`}
function updateDock(view){const group=projectData[view]||view==='travel'?'work':view==='now'?'about':view==='secret'?'home':view;$$('.panel-route').forEach(button=>{const active=button.dataset.open===group;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))});$$('.dock-item').forEach(button=>{const active=button.dataset.open===group;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')})}
function setPage(view){window.portfolioExtras?.unmount();content.innerHTML=pageMarkup(view);content.scrollTop=0;currentView=view;updateDock(view);if(!reduced)content.animate([{opacity:0,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'cubic-bezier(.16,1,.3,1)'});wireTactile(content);window.portfolioExtras?.mount(view);history.replaceState(null,'','#'+view);$('#scene-status').textContent=projectData[view]?projectData[view].name:view==='work'?'My projects':view==='about'?'About To’rabek':'Contact To’rabek'}
function openPanel(view,origin){if(view==='home'){if(panel.open)closePanel();else window.scrollTo({top:0,behavior:reduced?'instant':'smooth'});return}if(closing)return;if(panel.open){setPage(view);content.querySelector('.panel-title')?.setAttribute('tabindex','-1');content.querySelector('.panel-title')?.focus({preventScroll:true});return}lastOrigin=origin||document.activeElement;setPage(view);panel.showModal();sceneActivity();document.body.style.overflow='hidden';const rect=panel.getBoundingClientRect(),source=lastOrigin?.getBoundingClientRect();const dx=source?source.left+source.width/2-(rect.left+rect.width/2):0,dy=source?source.top+source.height/2-(rect.top+rect.height/2):30;panel._source={dx,dy};if(!reduced)panel.animate([{opacity:0,transform:`translate(${dx*.65}px,${dy*.65}px) scale(.38)`},{opacity:1,transform:'translate(0,0) scale(1)',offset:.8},{opacity:1,transform:'translate(0,0) scale(1)'}],{duration:560,easing:'cubic-bezier(.16,1,.3,1)'});$('.panel-close').focus({preventScroll:true})}
async function closePanel(){if(!panel.open||closing)return;closing=true;if(!reduced){const {dx,dy}=panel._source||{dx:0,dy:20};await panel.animate([{opacity:1,transform:'translate(0,0) scale(1)'},{opacity:0,transform:`translate(${dx*.30}px,${dy*.30}px) scale(.8)`}],{duration:280,easing:'cubic-bezier(.4,0,1,1)'}).finished.catch(()=>{})}window.portfolioExtras?.unmount();panel.close();sceneActivity();document.body.style.overflow='';currentView='home';updateDock('home');history.replaceState(null,'',location.pathname+location.search);lastOrigin?.focus({preventScroll:true});closing=false}
document.addEventListener('click',e=>{const target=e.target.closest('[data-open]');if(target){if(target.tagName==='A'){if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();}openPanel(target.dataset.open,target);if(target.dataset.open!=='home')chime(3)}const project=e.target.closest('[data-project]');if(project){openPanel(project.dataset.project,project);chime(7)}});$('.panel-close').addEventListener('click',closePanel);panel.addEventListener('cancel',e=>{e.preventDefault();closePanel()});panel.addEventListener('click',e=>{if(e.target===panel){const r=panel.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel()}});
function wireTactile(root=document){root.querySelectorAll('.tactile:not([data-wired])').forEach(el=>{el.dataset.wired='true';const release=()=>el.classList.remove('pressing');el.addEventListener('pointerdown',()=>el.classList.add('pressing'));['pointerup','pointercancel','pointerleave','blur'].forEach(event=>el.addEventListener(event,release));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')el.classList.add('pressing')});el.addEventListener('keyup',release)})}wireTactile();
const initial=location.hash.slice(1);if(['work','about','contact',...Object.keys(projectData)].includes(initial))openPanel(initial,$(`[data-open="${projectData[initial]?'work':initial}"]`));
